pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let post = (post_residual as f64).clamp(0.0, capacity);
    let residual = (bin_residual as f64).clamp(0.0, capacity);
    let mean = mean_residual.clamp(0.0, capacity);
    let empty_bin = (bin_residual == bin_capacity) as u8 as f64;
    let last_chance = (fitting_bins_count == 1) as u8 as f64;
    let lookahead = next_item_size as f64;

    let fill_ratio = (item / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let progress2 = progress * progress;
    let progress3 = progress2 * progress;

    let mut score = post;
    score += capacity * 0.45 * post_ratio * post_ratio;
    score -= capacity * 0.30 * progress * post_ratio;
    score -= capacity * 0.22 * progress2 * post_ratio * post_ratio;
    score += capacity * 0.16 * progress3 * (1.0 - fill_ratio);
    score += capacity * 0.12 * post_ratio * (1.0 - fill_ratio);
    score -= capacity * 0.10 * progress * fill_ratio * (1.0 - post_ratio);
    score += capacity * 0.08 * (post_ratio - (mean / capacity)).abs();
    score += capacity * 0.10 * (1.0 - progress) * post_ratio * post_ratio;
    score -= capacity * 0.18 * last_chance * (1.0 - post_ratio);
    score -= capacity * 0.16 * empty_bin * progress2 * fill_ratio;
    score += capacity * 0.12 * empty_bin * (1.0 - progress) * post_ratio;
    score -= capacity * 0.14 * progress * lookahead * post_ratio * (1.0 - fill_ratio);
    score += capacity * 0.05 * (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * post_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strictly penalize dead space that cannot accommodate the next item.
    if (next_item_size == 0 || post_residual < next_item_size) && post_residual > 0 {
        score += 120.0 + (post_residual as f64).powi(2) * 0.08;
    }

    // Prefer leaving a coherent gap that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    }

    // Reward tighter placements, especially when a bin can only just fit.
    let utilization = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * utilization;

    // Encourage using existing bins, with stronger pressure as the stream grows.
    let stream_pressure = (step_index as f64 / total_items.max(1) as f64).min(1.0);
    score += (open_bins_count as f64).powf(1.15) * (3.0 + 7.0 * stream_pressure);

    // A last fitting opportunity deserves a decisive preference.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Keep the empty-bin candidate competitive only when the current item is large.
    if bin_residual == bin_capacity {
        score += 25.0 + item_size as f64 * 0.35;
    }

    // Slightly favor bins whose remaining capacity is near the stream's average,
    // while avoiding pathological excess residual space.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.045;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item = item_size as f64;
    let capacity = bin_capacity.max(1) as f64;
    let residual = bin_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    // Strictly discourage fragmented leftovers that are unlikely to be useful.
    let dead_space_penalty = if post_residual == 0 {
        0.0
    } else if post_residual < item.min(next.max(1.0)) {
        (item.min(next.max(1.0)) - post_residual as f64) * 2.5
    } else {
        (post_residual as f64) * 0.35
    };

    // A new empty bin avoids all existing fragmentation, so charge it for wasting capacity.
    let empty_bin_penalty = if bin_residual == bin_capacity {
        8.0 + item * 0.15
    } else {
        0.0
    };

    // Tight fits are generally preferable, but exact closure is especially valuable.
    let tightness_reward = if bin_residual == bin_capacity {
        0.0
    } else if post_residual == 0 {
        6.0
    } else {
        (residual - post_residual as f64).min(item) * 0.08
    };

    // More open bins imply greater pressure to consolidate rather than add another.
    let consolidation_reward = (open_bins_count as f64).sqrt() * 1.2;
    let pressure_penalty = if fitting_bins_count <= 1 {
        (open_bins_count as f64) * 0.45
    } else {
        0.0
    };

    // Near the end of the stream, preserve opportunities for large remaining items.
    let lookahead_penalty = if next > 0.0 && post_residual > 0 && (post_residual as f64) < next {
        (next - post_residual as f64) * (0.8 + progress)
    } else {
        0.0
    };

    score += dead_space_penalty;
    score += empty_bin_penalty;
    score += pressure_penalty;
    score += lookahead_penalty;
    score -= tightness_reward;
    score -= consolidation_reward;

    // Prefer candidates whose residual is close to the population mean, mildly reducing
    // the chance of creating an unusually tight or unusually wasteful bin.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64).abs() * 0.03;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residual fragments that are too small to accommodate the
    // lookahead item (or the next smallest plausible item) are costly.
    let lookahead = next_item_size.max(1);
    if (post_residual as u32) < lookahead {
        let severity = (lookahead - post_residual) as f64;
        score += severity * 2.0;
        // Very small gaps are effectively unusable and strongly penalized.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Prefer filling the bin tightly, with a modest preference for larger
    // placements when residuals are comparable.
    score -= (item_size as f64) * 0.05;

    // Pressure from many open bins: opening another bin becomes less
    // attractive as the inventory of partially filled bins grows.
    score += open_bins_count as f64 * 0.35;

    // If this is the only fitting bin, favor using it rather than opening
    // a fresh bin, though do not override severe dead-space costs.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // A new bin has no prior dead space; slightly reward it only when the
    // current bin would leave a poor residual and the stream is well advanced.
    if bin_residual == bin_capacity {
        score -= 5.0;
        score -= (step_index as f64 / total_items.max(1) as f64) * 2.0;
    }

    // Keep residual occupancy near the average open-bin residual, avoiding
    // both systematically loose bins and overly concentrated remnants.
    score += ((post_residual as f64) - mean_residual).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer the empty bin only when existing placements would create severe
    // fragmentation; the new-bin candidate is distinguishable by full residual.
    if bin_residual == bin_capacity {
        score -= bin_capacity as f64 * 0.25;
    }

    // Reward an exact fit strongly because it closes the bin without waste.
    if post_residual == 0 {
        score -= 55.0;
    }

    // Lookahead: preserve enough room for the next item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_slack = (post_residual - next_item_size) as f64;
        score -= 18.0 + (100.0 - lookahead_slack.min(100.0)) * 0.08;
    } else if next_item_size > 0 {
        // Penalize consuming the bin in a way that blocks the next item.
        let deficit = (next_item_size - post_residual) as f64;
        score += 8.0 + deficit * 0.45;
    }

    // Favor placements whose resulting residual is close to the mean residual,
    // reducing dispersion among open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.18;

    // Reward using a bin whose fit is scarce, especially when it is the only
    // feasible open bin; this reduces the chance of opening another bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).min(8.0) * 1.5;
    }

    // Mildly prefer tighter fits, but not at the cost of the lookahead term.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fill_ratio.clamp(0.0, 1.0)) * 5.0;

    // Toward the end of a long stream, favor immediate closure and avoid
    // opening bins unnecessarily; early on, preserve flexibility more.
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    score -= progress * (if post_residual == 0 { 12.0 } else { 2.0 });

    // New bins carry a modest structural penalty, allowing them to win only
    // when the current open-bin options are comparatively poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if open_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

