pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let normalized_post = post_residual as f64 / capacity;
    let normalized_item = item / capacity;
    let utilization = 1.0 - normalized_post;

    score += 55.0 * normalized_post * normalized_post;
    score -= 18.0 * progress * utilization;
    score -= 9.0 * progress * normalized_item * (1.0 - normalized_post);
    score += 24.0 * (1.0 - progress) * normalized_post * normalized_post;
    score += 3.0 * (mean_residual - post_residual as f64) * (1.0 - progress);
    score -= 7.0 * utilization * next_item_size as f64 / capacity;

    if fitting_bins_count <= 1 {
        score -= 4.0 * progress * utilization;
    } else {
        score += 2.0 * progress * open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    }

    score += (bin_residual as f64 - item - post_residual as f64).abs() * 0.0;
    score
